"use client"

import type React from "react"

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Textarea } from "@/components/ui/textarea"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { MapPin, Calendar, User, AlertCircle, Clock, CheckCircle2, MessageSquare } from "lucide-react"
import Link from "next/link"
import { useState, useEffect } from "react"
import dynamic from "next/dynamic"

// Dynamic import for Leaflet map
const MapContainer = dynamic(() => import("react-leaflet").then((mod) => mod.MapContainer), { ssr: false })
const TileLayer = dynamic(() => import("react-leaflet").then((mod) => mod.TileLayer), { ssr: false })
const Marker = dynamic(() => import("react-leaflet").then((mod) => mod.Marker), { ssr: false })
const Popup = dynamic(() => import("react-leaflet").then((mod) => mod.Popup), { ssr: false })

const statusConfig = {
  NOUVEAU: { label: "Nouveau", color: "bg-blue-500", icon: AlertCircle },
  EN_ATTENTE: { label: "En attente", color: "bg-yellow-500", icon: Clock },
  EN_COURS: { label: "En cours", color: "bg-orange-500", icon: Clock },
  RESOLU: { label: "Résolu", color: "bg-green-500", icon: CheckCircle2 },
}

const priorityConfig = {
  BASSE: { label: "Basse", variant: "secondary" as const },
  MOYENNE: { label: "Moyenne", variant: "default" as const },
  HAUTE: { label: "Haute", variant: "destructive" as const },
}

// Mock data
const mockSignalement = {
  id: 1,
  titre: "Nid de poule avenue Victor Hugo",
  description:
    "Grand trou sur la chaussée qui endommage les véhicules. Le problème s'aggrave avec les récentes pluies et devient dangereux pour les cyclistes et les deux-roues.",
  categorie: "Nids de poule",
  statut: "EN_COURS",
  priorite: "HAUTE",
  dateCreation: "2024-01-15T10:30:00",
  latitude: 48.8566,
  longitude: 2.3522,
  photoUrl: "/large-street-pothole.png",
  utilisateur: {
    nom: "Dupont",
    prenom: "Marie",
  },
}

const mockComments = [
  {
    id: 1,
    texte: "Problème bien reçu, intervention prévue dans les prochains jours.",
    dateCreation: "2024-01-16T14:20:00",
    auteur: { nom: "Martin", prenom: "Pierre", role: "TECHNICIEN" },
  },
  {
    id: 2,
    texte:
      "Merci pour le retour. Le problème est vraiment dangereux, je l'ai signalé car plusieurs accidents ont failli se produire.",
    dateCreation: "2024-01-16T16:45:00",
    auteur: { nom: "Dupont", prenom: "Marie", role: "CITOYEN" },
  },
]

export default function SignalementDetailPage({ params }: { params: { id: string } }) {
  const [newComment, setNewComment] = useState("")
  const [isMapReady, setIsMapReady] = useState(false)

  useEffect(() => {
    setIsMapReady(true)
  }, [])

  const handleCommentSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    console.log("[v0] New comment:", newComment)
    setNewComment("")
  }

  const statusInfo = statusConfig[mockSignalement.statut as keyof typeof statusConfig]
  const priorityInfo = priorityConfig[mockSignalement.priorite as keyof typeof priorityConfig]
  const StatusIcon = statusInfo.icon

  return (
    <div className="min-h-screen bg-background">
      {/* Main Content */}
      <main className="container mx-auto px-4 py-8">
        <div className="mb-6">
          <Link href="/signalements" className="text-sm text-muted-foreground hover:text-foreground">
            ← Retour aux signalements
          </Link>
        </div>

        <div className="grid gap-8 lg:grid-cols-3">
          {/* Main Content */}
          <div className="lg:col-span-2">
            <Card className="mb-6">
              <CardHeader>
                <div className="mb-4 flex flex-wrap items-start justify-between gap-2">
                  <div className="flex gap-2">
                    <Badge variant={priorityInfo.variant}>{priorityInfo.label}</Badge>
                    <div
                      className={`flex items-center gap-1 rounded-full px-2 py-1 text-xs text-white ${statusInfo.color}`}
                    >
                      <StatusIcon className="h-3 w-3" />
                      {statusInfo.label}
                    </div>
                  </div>
                  <span className="text-sm text-muted-foreground">#{mockSignalement.id}</span>
                </div>
                <CardTitle className="text-2xl">{mockSignalement.titre}</CardTitle>
                <CardDescription className="flex items-center gap-4 pt-2">
                  <span className="flex items-center gap-1">
                    <User className="h-4 w-4" />
                    {mockSignalement.utilisateur.prenom} {mockSignalement.utilisateur.nom}
                  </span>
                  <span className="flex items-center gap-1">
                    <Calendar className="h-4 w-4" />
                    {new Date(mockSignalement.dateCreation).toLocaleDateString("fr-FR")}
                  </span>
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                <img
                  src={mockSignalement.photoUrl || "/placeholder.svg"}
                  alt={mockSignalement.titre}
                  className="w-full rounded-lg object-cover"
                />
                <div>
                  <h3 className="mb-2 font-semibold">Description</h3>
                  <p className="text-muted-foreground">{mockSignalement.description}</p>
                </div>
                <div>
                  <h3 className="mb-2 font-semibold">Catégorie</h3>
                  <Badge variant="outline">{mockSignalement.categorie}</Badge>
                </div>
              </CardContent>
            </Card>

            {/* Comments Section */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <MessageSquare className="h-5 w-5" />
                  Commentaires ({mockComments.length})
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-6">
                {mockComments.map((comment) => (
                  <div key={comment.id} className="flex gap-4">
                    <Avatar>
                      <AvatarFallback>
                        {comment.auteur.prenom[0]}
                        {comment.auteur.nom[0]}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1">
                      <div className="mb-1 flex items-center gap-2">
                        <span className="font-semibold">
                          {comment.auteur.prenom} {comment.auteur.nom}
                        </span>
                        <Badge
                          variant={comment.auteur.role === "TECHNICIEN" ? "default" : "secondary"}
                          className="text-xs"
                        >
                          {comment.auteur.role === "TECHNICIEN" ? "Technicien" : "Citoyen"}
                        </Badge>
                        <span className="text-xs text-muted-foreground">
                          {new Date(comment.dateCreation).toLocaleDateString("fr-FR")}
                        </span>
                      </div>
                      <p className="text-sm text-muted-foreground">{comment.texte}</p>
                    </div>
                  </div>
                ))}

                <form onSubmit={handleCommentSubmit} className="space-y-4 border-t border-border pt-6">
                  <Textarea
                    placeholder="Ajouter un commentaire..."
                    value={newComment}
                    onChange={(e) => setNewComment(e.target.value)}
                    rows={3}
                  />
                  <Button type="submit">Publier le commentaire</Button>
                </form>
              </CardContent>
            </Card>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Localisation</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="h-64 w-full overflow-hidden rounded-lg">
                  {isMapReady && (
                    <MapContainer
                      center={[mockSignalement.latitude, mockSignalement.longitude]}
                      zoom={15}
                      style={{ height: "100%", width: "100%" }}
                    >
                      <TileLayer
                        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
                      />
                      <Marker position={[mockSignalement.latitude, mockSignalement.longitude]}>
                        <Popup>{mockSignalement.titre}</Popup>
                      </Marker>
                    </MapContainer>
                  )}
                </div>
                <div className="mt-4 flex items-start gap-2 text-sm text-muted-foreground">
                  <MapPin className="mt-0.5 h-4 w-4 shrink-0" />
                  <span>
                    {mockSignalement.latitude.toFixed(4)}, {mockSignalement.longitude.toFixed(4)}
                  </span>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Actions</CardTitle>
              </CardHeader>
              <CardContent className="space-y-2">
                <Button variant="outline" className="w-full bg-transparent">
                  Modifier le statut
                </Button>
                <Button variant="outline" className="w-full bg-transparent">
                  Assigner à un technicien
                </Button>
                <Button
                  variant="outline"
                  className="w-full text-destructive hover:bg-destructive hover:text-destructive-foreground bg-transparent"
                >
                  Supprimer le signalement
                </Button>
              </CardContent>
            </Card>
          </div>
        </div>
      </main>
    </div>
  )
}
